def gen(rng):
    def make_tree(n, kind):
        edges = []
        for i in range(1, n):
            if kind == 'path':
                par = i - 1
            elif kind == 'star':
                par = 0
            elif kind == 'cater':
                par = i - 1 if i % 2 == 1 else max(0, i - 2)
            elif kind == 'broom':
                par = i - 1 if i < n // 2 else n // 2 - 1
            else:
                par = rng.randrange(i)
            edges.append((par, i))
        return edges

    def fmt(n, edges, known, perm=None):
        if perm is None:
            perm = list(range(n))
        lines = [str(n)]
        for u, v in edges:
            lines.append(str(perm[u]) + ' ' + str(perm[v]))
        lines.append(str(len(known)))
        for i, t in known:
            lines.append(str(perm[i]) + ' ' + str(t))
        return '\n'.join(lines)

    def build(n, kind, k, lo_root, hi_root, shuffle=True):
        edges = make_tree(n, kind)
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        val = [0] * n
        val[0] = rng.randint(lo_root, hi_root)
        for u, v in edges:
            # edges are listed parent first, so val[u] is set before val[v]
            if val[u] == 1 or rng.random() < 0.5:
                val[v] = val[u] + 1
            else:
                val[v] = val[u] - 1
        idx = rng.sample(range(n), k)
        known = [(i, val[i]) for i in idx]
        perm = list(range(n))
        if shuffle:
            rng.shuffle(perm)
        return fmt(n, edges, known, perm)

    tests = [
        '1\n1\n0 7',
        '1\n1\n0 1',
        '2\n0 1\n1\n0 1',
        '2\n0 1\n1\n1 5',
        '5\n0 1\n1 2\n2 3\n3 4\n2\n0 3\n4 3',
        '5\n0 1\n0 2\n0 3\n0 4\n1\n1 5',
        '3\n0 1\n1 2\n1\n1 1',
        '4\n0 1\n1 2\n2 3\n2\n0 2\n3 1',
    ]
    for _ in range(50):
        n = rng.randint(1, 9)
        kind = rng.choice(['rand', 'path', 'star', 'cater', 'broom'])
        k = rng.randint(1, min(n, 3))
        tests.append(build(n, kind, k, 1, rng.choice([2, 4, 8])))
    N = 100000
    tests.append(build(N, 'path', 2, 1, 10 ** 9 - N))
    tests.append(build(N, 'rand', 1, 1, 10 ** 9 - N))
    tests.append(build(N, 'rand', 50, 1, 20))
    tests.append(build(N, 'star', 3, 5, 10 ** 9 - 5))
    tests.append(build(N, 'cater', N, 1, 10 ** 9 - N))
    tests.append(build(N, 'broom', 1, 1, 10 ** 9 - N))
    tests.append(build(N, 'path', 1, 1, 1))
    return tests

